public double findMedianSortedArrays(int[] a, int[] b) {
    if (a.length > b.length) return findMedianSortedArrays(b, a);
    int m = a.length, n = b.length, half = (m + n + 1) / 2;
    int lo = 0, hi = m;
    while (lo <= hi) {
        int i = lo + (hi - lo) / 2;   // cut in a
        int j = half - i;             // cut in b
        int l1 = (i == 0) ? Integer.MIN_VALUE : a[i - 1];
        int r1 = (i == m) ? Integer.MAX_VALUE : a[i];
        int l2 = (j == 0) ? Integer.MIN_VALUE : b[j - 1];
        int r2 = (j == n) ? Integer.MAX_VALUE : b[j];
        if (l1 <= r2 && l2 <= r1) {
            if (((m + n) & 1) == 1) return Math.max(l1, l2);
            return (Math.max(l1, l2) + Math.min(r1, r2)) / 2.0;
        } else if (l1 > r2) hi = i - 1;   // too many from a
        else lo = i + 1;                  // too few from a
    }
    return 0.0;   // unreachable for valid input
}

public int minEatingSpeed(int[] piles, int h) {
    int lo = 1, hi = 0;
    for (int p : piles) hi = Math.max(hi, p);
    while (lo < hi) {
        int k = lo + (hi - lo) / 2;
        if (hours(piles, k) <= h) hi = k;   // feasible -> try slower
        else lo = k + 1;
    }
    return lo;
}
private long hours(int[] piles, int k) {
    long h = 0;
    for (int p : piles) h += (p + k - 1) / k;   // ceil(p/k)
    return h;
}

public int shipWithinDays(int[] w, int days) {
    int lo = 0, hi = 0;
    for (int x : w) { lo = Math.max(lo, x); hi += x; }
    while (lo < hi) {
        int cap = lo + (hi - lo) / 2;
        if (needed(w, cap) <= days) hi = cap;
        else lo = cap + 1;
    }
    return lo;
}
private int needed(int[] w, int cap) {
    int d = 1, cur = 0;
    for (int x : w) {
        if (cur + x > cap) { d++; cur = 0; }
        cur += x;
    }
    return d;
}

public int splitArray(int[] nums, int k) {
    int lo = 0, hi = 0;
    for (int x : nums) { lo = Math.max(lo, x); hi += x; }
    while (lo < hi) {
        int cap = lo + (hi - lo) / 2;
        if (pieces(nums, cap) <= k) hi = cap;
        else lo = cap + 1;
    }
    return lo;
}
private int pieces(int[] nums, int cap) {
    int p = 1, cur = 0;
    for (int x : nums) {
        if (cur + x > cap) { p++; cur = 0; }
        cur += x;
    }
    return p;
}

public int splitArrayDP(int[] nums, int k) {
    int n = nums.length;
    long[] pre = new long[n + 1];
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
    long[][] dp = new long[n + 1][k + 1];
    for (long[] row : dp) Arrays.fill(row, Long.MAX_VALUE);
    dp[0][0] = 0;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= k; j++)
            for (int p = j - 1; p < i; p++) {
                if (dp[p][j - 1] == Long.MAX_VALUE) continue;
                long largest = Math.max(dp[p][j - 1], pre[i] - pre[p]);
                dp[i][j] = Math.min(dp[i][j], largest);
            }
    return (int) dp[n][k];
}

public int findMin(int[] nums) {
    int lo = 0, hi = nums.length - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (nums[mid] > nums[hi]) lo = mid + 1;
        else if (nums[mid] < nums[hi]) hi = mid;
        else hi--;                 // duplicate: shrink
    }
    return nums[lo];
}

public int smallestDistancePair(int[] nums, int k) {
    Arrays.sort(nums);
    int n = nums.length;
    int lo = 0, hi = nums[n - 1] - nums[0];
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (countLE(nums, mid) >= k) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}
private int countLE(int[] nums, int d) {
    int cnt = 0, left = 0;
    for (int right = 0; right < nums.length; right++) {
        while (nums[right] - nums[left] > d) left++;
        cnt += right - left;
    }
    return cnt;
}

public int kthSmallest(int[][] matrix, int k) {
    int n = matrix.length;
    int lo = matrix[0][0], hi = matrix[n - 1][n - 1];
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (countLE(matrix, mid) >= k) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}
private int countLE(int[][] m, int x) {
    int n = m.length, cnt = 0, row = n - 1, col = 0;
    while (row >= 0 && col < n) {
        if (m[row][col] <= x) { cnt += row + 1; col++; }
        else row--;
    }
    return cnt;
}

public int kthSmallestHeap(int[][] matrix, int k) {
    int n = matrix.length;
    // entries: {value, row, col}
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
    for (int r = 0; r < n; r++) pq.offer(new int[]{matrix[r][0], r, 0});
    int val = 0;
    for (int i = 0; i < k; i++) {
        int[] cur = pq.poll();
        val = cur[0];
        int r = cur[1], c = cur[2];
        if (c + 1 < n) pq.offer(new int[]{matrix[r][c + 1], r, c + 1});
    }
    return val;
}

public double minmaxGasDist(int[] stations, int k) {
    double lo = 0, hi = 0;
    for (int i = 1; i < stations.length; i++)
        hi = Math.max(hi, stations[i] - stations[i - 1]);
    while (hi - lo > 1e-6) {
        double mid = lo + (hi - lo) / 2;
        if (needed(stations, mid) <= k) hi = mid;   // feasible -> try smaller
        else lo = mid;
    }
    return lo;
}
private long needed(int[] stations, double d) {
    long cnt = 0;
    for (int i = 1; i < stations.length; i++)
        cnt += (long) ((stations[i] - stations[i - 1]) / d);
    return cnt;
}

public int maxDistance(int[] position, int m) {
    Arrays.sort(position);
    int lo = 1, hi = position[position.length - 1] - position[0];
    int ans = 0;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (canPlace(position, m, mid)) { ans = mid; lo = mid + 1; }
        else hi = mid - 1;
    }
    return ans;
}
private boolean canPlace(int[] pos, int m, int minDist) {
    int count = 1, last = pos[0];
    for (int i = 1; i < pos.length; i++) {
        if (pos[i] - last >= minDist) {
            count++;
            last = pos[i];
            if (count == m) return true;
        }
    }
    return count >= m;
}

public int matrixMedian(int[][] matrix) {
    int r = matrix.length, c = matrix[0].length;
    int lo = Integer.MAX_VALUE, hi = Integer.MIN_VALUE;
    for (int i = 0; i < r; i++) {
        lo = Math.min(lo, matrix[i][0]);
        hi = Math.max(hi, matrix[i][c - 1]);
    }
    int need = (r * c) / 2;   // want smallest value with countLE > need
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (countLE(matrix, mid) > need) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}
private int countLE(int[][] matrix, int x) {
    int cnt = 0;
    for (int[] row : matrix) cnt += upperBound(row, x);
    return cnt;
}
private int upperBound(int[] row, int x) {
    int lo = 0, hi = row.length;   // count of elements <= x
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (row[mid] <= x) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}
